package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func insertDist(dist int, c rune, distMap map[rune]int, diff int) {
	if dist <= 13+diff {
		if dist-diff >= 0 {
			distMap[c] = dist - diff
		} else {
			distMap[c] = -(dist - diff)
		}
	} else {
		distMap[c] = 26 + diff - dist
	}
}

func solve(input io.Reader, output io.Writer) {
	reader := bufio.NewReader(input)
	var inputStr string

	distA := make(map[rune]int)
	distC := make(map[rune]int)
	distT := make(map[rune]int)
	distG := make(map[rune]int)

	alphabet := "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
	for i, c := range alphabet {
		dist := i
		insertDist(dist, c, distA, 0)
		insertDist(dist, c, distC, 2)
		if dist <= 6 {
			distT[c] = 7 + dist
		} else {
			if dist-19 >= 0 {
				distT[c] = dist - 19
			} else {
				distT[c] = -(dist - 19)
			}
		}
		insertDist(dist, c, distG, 6)
	}

	line, _ := reader.ReadString('\n')
	fmt.Sscanf(line, "%s", &inputStr)
	var n int
	fmt.Sscanf(inputStr, "%d", &n)

	line, _ = reader.ReadString('\n')
	s := line
	if len(s) > 0 && (s[len(s)-1] == '\n' || s[len(s)-1] == '\r') {
		s = s[:len(s)-1]
		if len(s) > 0 && s[len(s)-1] == '\r' {
			s = s[:len(s)-1]
		}
	}

	charVec := []rune(s)
	minSum := -1
	for i := 0; i < n-3; i++ {
		sum := distA[charVec[i]] +
			distC[charVec[i+1]] +
			distT[charVec[i+2]] +
			distG[charVec[i+3]]

		if minSum == -1 || sum < minSum {
			minSum = sum
		}
	}

	fmt.Fprintf(output, "%d\n", minSum)
}

func main() {
	solve(os.Stdin, os.Stdout)
}

